export interface ConsolidationSummary {
  readonly schemaVersion: 1;
  readonly inputRowCount: number;
  readonly distinctSellerEntryCount: number;
  readonly duplicateInputCount: number;
  readonly matchedProducts: number;
  readonly insertedProducts: number;
  readonly insertedLinks: number;
  readonly alreadyPresentLinks: number;
  readonly rejectedRows: number;
  readonly ambiguousRows: number;
  readonly elapsedMilliseconds: number;
  readonly dryRun: boolean;
  readonly databasePath: string;
}

/** SDD-003+ own catalog migrations and mutation; this slice provides deterministic input planning. */
export function planConsolidation(input: ValidatedInput, databasePath: string, dryRun: boolean, elapsedMilliseconds: number): ConsolidationSummary {
  return {
    schemaVersion: 1,
    inputRowCount: input.inputRowCount,
    distinctSellerEntryCount: input.distinctSellerEntryCount,
    duplicateInputCount: input.duplicateInputCount,
    matchedProducts: 0,
    insertedProducts: 0,
    insertedLinks: 0,
    alreadyPresentLinks: 0,
    rejectedRows: 0,
    ambiguousRows: 0,
    elapsedMilliseconds,
    dryRun,
    databasePath,
  };
}
"}

{"file_path":"src/adapters/reporter.ts","content":"import type { RowDiagnostic, ValidationFailure } from "../domain/input.ts";
import type { ConsolidationSummary } from "../application/consolidation.ts";

export function renderJson(value: ConsolidationSummary | ValidationFailure): string {
  return `${JSON.stringify(value)}\n`;
}

export function renderText(summary: ConsolidationSummary): string {
  return `catalog consolidation: ${summary.distinctSellerEntryCount} entries planned; ${summary.insertedProducts} products and ${summary.insertedLinks} links inserted${summary.dryRun ? " (dry run)" : ""}\n`;
}

export function renderDiagnostics(diagnostics: readonly RowDiagnostic[], truncated: boolean): string {
  const rows = diagnostics.map((item) => `${item.index === 0 ? "input" : `row ${item.index}`}: ${item.code}: ${item.message}`);
  if (truncated) rows.push("diagnostics truncated");
  return `${rows.join("\n")}\n`;
}
"}

