import { access, constants, stat } from "node:fs/promises";
import { DatabaseSync } from "node:sqlite";

/** Validates that a supplied catalog can be opened without starting a write transaction. */
export async function verifyDatabase(path: string): Promise<void> {
  const details = await stat(path);
  if (!details.isFile()) throw new Error("database path is not a file");
  await access(path, constants.R_OK);
  const database = new DatabaseSync(path, { open: true, readOnly: true });
  database.close();
}

